//! Default tone instructions, copied verbatim from the Swift Config.swift string literals.

pub const SUPERCASUAL: &str = "Tone: super casual text to a close friend. Everything lowercase, including i, but names keep their capitals. Barely any punctuation: no commas at all, a full stop only between sentences when the message has several and never at the very end, question marks and apostrophes kept, no exclamation marks. Words just flow. Laughter and reactions (haha, lol, oh, wow) stay. Fillers like um and uh are removed.\nExample: \"Um, so, tomorrow is fine. See you then.\" -> \"so tomorrow is fine see you then\"\nExample: \"Haha. No, I really don't want to do it, but can you do it?\" -> \"haha no i really don't want to do it but can you do it?\"\nExample: \"Sure, see you at 5. Bring the charger.\" -> \"sure see you at 5. bring the charger\"\nExample: \"Hey Jordan, thanks a lot for reaching out! Haha, I appreciate the kind thoughts. I also locked in the place a few weeks before. Hope you can find someone to fill the spot soon.\" -> \"hey Jordan thanks a lot for reaching out haha i appreciate the kind thoughts. i also locked in the place a few weeks before hope you can find someone to fill the spot soon\"\nQuotation marks around quoted or mentioned words and titles still apply.";

pub const CASUAL: &str = "Tone: casual message to a friend or a colleague you are on first-name terms with. Lowercase i and lowercase sentence starts, but names keep their capitals. Normal punctuation: commas between clauses and a full stop at the end of every sentence including the last one, question marks kept, no exclamation marks or semicolons. Contractions and everyday wording stay as spoken, nothing gets formalised. Laughter and reactions (haha, lol, oh, wow) stay. Fillers like um and uh are removed.\nExample: \"Um, so, tomorrow is fine. See you then.\" -> \"so tomorrow is fine. see you then.\"\nExample: \"Haha. No, I really don't want to do it, but can you do it?\" -> \"haha no, i really don't want to do it, but can you do it?\"\nExample: \"Hey Jordan, thanks a lot for reaching out! Haha, I appreciate the kind thoughts. I also locked in the place a few weeks before.\" -> \"hey Jordan, thanks a lot for reaching out haha, i appreciate the kind thoughts. i also locked in the place a few weeks before.\"";

pub const PROFESSIONAL: &str = "Tone: message to a colleague or client. Normal capitalization and punctuation, complete sentences, no slang. Keep the speaker's own words and phrasing; fix grammar and remove fillers, but do not reword, formalize or restructure what they said.";

